import { hideChartPopover, showChartPopover } from "../chart-board/board-util";

const generateSankeyDefaultTooltip = (datum, _event) => {
	if (datum.id) {
		return `<div class="--hbr-sankey-popover-entity">
      <div class="--hbr-sankey-popover-color" style="background:${datum.color}"></div>
      ${datum.id}
    </div>`;
	}
	return `<div class="--hbr-sankey-popover-entity">
      <table>
        <tr>
          <td>Source:</td>
          <td>
            <div class="--hbr-sankey-popover-color" style="background:${datum.source.color}"></div>
            ${datum.source.id}
          </td>
        </tr>
        <tr>
          <td>Target:</td>
          <td>
            <div class="--hbr-sankey-popover-color" style="background:${datum.target.color}"></div>
            ${datum.target.id}
          </td>
        </tr>
        <tr>
          <td>Value:</td>
          <td class="--hbr-sankey-popover-value">
            ${datum.value}
          </td>
        </tr>
      </table>
    </div>
  </div>`;
};

const generateSankeyLegendTooltip = (datum, _event) => {
	return `<div class="--hbr-sankey-popover-entity">
      <div class="--hbr-sankey-popover-color" style="background:${datum.color}"></div>
      ${datum.id}
    </div>`;
};

const generateSankeyDefaultTooltipCategorical = (datum) => {
	if (datum.id) {
		const datumTargetTable = datum.sourceLinks?.length
			? datum.sourceLinks.reduce((acc, cur, idx) => {
					return `${acc}<tr><td><div class="--sankey-item"><div class="--color-box" style="background:${
						cur.target.color
					}"></div>${cur.target.id}</div>
          </td><td class="--sankey-value --semibold">${
						cur.target.value
					}</td></tr>${idx === datum.sourceLinks.length - 1 ? "</table>" : ""}`;
			  }, "<span class='--semibold'>Destination:</span><table>")
			: "";
		const datumSourceTable = datum.targetLinks?.length
			? datum.targetLinks.reduce((acc, cur, idx) => {
					return `${acc}<tr><td><div class="--sankey-item"><div class="--color-box" style="background:${
						cur.source.color
					}"></div>${cur.source.id}</div>
          </td><td class="--sankey-value --semibold">${
						cur.source.value
					}</td></tr>${idx === datum.targetLinks.length - 1 ? "</table>" : ""}`;
			  }, "<span class='--semibold'>Source:</span><table>")
			: "";

		return `<div class="--hbr-sankey-popover-entity-categorical">
        <table>
          <tr>
            <td>
              <div class="--sankey-item">
                <div class="--color-box" style="background:${datum.color}"></div>
                <div class="--semibold">${datum.id}</div>
              </div>
            </td>
            <td class="--sankey-value --semibold">
            ${datum.value}
            </td>
        </table>
        <hbr-divider></hbr-divider>
        ${datumSourceTable}
        ${datumTargetTable}
    </div>`;
	}
	return `<div class="--hbr-sankey-popover-entity-categorical">
        <span class='--semibold'>Source:</span>
        <table>
          <tr>
            <td>
              <div class="--sankey-item">
                <div class="--color-box" style="background:${datum.source.color}"></div>
                    ${datum.source.id}
              </div>
            </td>
            <td class="--sankey-value --semibold">
            ${datum.source.value}
            </td>
        </table>
    </div>
    <div class="--hbr-sankey-popover-entity-categorical">
        <span class='--semibold'>Destination:</span>
        <table>
          <tr>
            <td>
              <div class="--sankey-item">
                <div class="--color-box" style="background:${datum.target.color}"></div>
                    ${datum.target.id}
              </div>
            </td>
            <td class="--sankey-value --semibold">
            ${datum.target.value}
            </td>
        </table>
    </div>`;
};

const showSankeyItemTooltip = (
	data,
	event,
	tooltipRef,
	customItemTooltip,
	isCategorical,
) => {
	showChartPopover(
		tooltipRef,
		data,
		event,
		customItemTooltip,
		isCategorical
			? generateSankeyDefaultTooltipCategorical
			: generateSankeyDefaultTooltip,
	);
};
const hideSankeyTooltip = (tooltipRef) => {
	hideChartPopover(tooltipRef);
};

const showSankeyLegendTooltip = (
	data,
	event,
	tooltipRef,
	legendTooltipFunc,
) => {
	if (event.target) {
		showChartPopover(
			tooltipRef,
			data,
			event,
			legendTooltipFunc,
			generateSankeyLegendTooltip,
		);
	}
};
const convertSankeyDataToCSV = (data) => {
	let csv = "source,target,value\n";

	data.links.forEach((link) => {
		const { source, target, value } = link;
		csv += `${source},${target},${value}\n`;
	});

	return csv;
};

export {
	showSankeyItemTooltip,
	hideSankeyTooltip,
	showSankeyLegendTooltip,
	convertSankeyDataToCSV,
};
